'use strict';

var Float64Array = require( '@stdlib/array/float64' );
var dlasrt = require( './../lib/' );

var D = new Float64Array( [ 12, -3, 7.5, 0, 19, -8, 4, 4, 15, -1, 2.2, 9 ] );

dlasrt( 'I', 12, D );
console.log( D );

// Redefine the `D` array as it gets updated.
D = new Float64Array( [ 12, -3, 7.5, 0, 19, -8, 4, 4, 15, -1, 2.2, 9 ] );

dlasrt.ndarray( 'D', 12, D, 1, 0 );
console.log( D );
